import { marked } from 'marked';

export type Book = {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
	html: string;
};

const files = import.meta.glob('/content/books/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

function parse(slug: string, raw: string): Book {
	const m = raw.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
	const meta: Record<string, string> = {};
	for (const line of (m?.[1] ?? '').split('\n')) {
		const i = line.indexOf(':');
		if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
	}
	const unquote = (s: string) => s.replace(/^(["'])(.*)\1$/, '$2');
	const tags = (meta.tags ?? '')
		.replace(/^\[|\]$/g, '')
		.split(',')
		.map((t) => unquote(t.trim()))
		.filter(Boolean);
	return {
		slug,
		title: unquote(meta.title ?? slug),
		author: unquote(meta.author ?? ''),
		year: Number(meta.year),
		rating: Number(meta.rating),
		tags,
		html: marked.parse(m?.[2] ?? '', { async: false }) as string
	};
}

const books: Book[] = Object.entries(files)
	.map(([path, raw]) => parse(path.split('/').pop()!.replace(/\.md$/, ''), raw))
	.sort((a, b) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0));

export const getBooks = () => books;
export const getBook = (slug: string) => books.find((b) => b.slug === slug);
