export type Fields = { name: string; email: string; message: string };
export type Errors = Partial<Record<keyof Fields, string>>;

export function validate(v: Fields): Errors {
	const e: Errors = {};
	if (!v.name.trim()) e.name = 'Name is required.';
	const email = v.email.trim();
	if (!email) e.email = 'Email is required.';
	else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) e.email = 'Enter a valid email address.';
	if (v.message.trim().length < 20) e.message = 'Message must be at least 20 characters.';
	return e;
}
